using HPD.Agent.Audio.Runtime.Providers;
using HPD.Agent.Authority;

namespace HPD.Agent.LiveAudio.Contracts.Tests;

public sealed class ProviderAdjacentOwnerPortsTests
{
    [Fact] public void All_seven_adjacent_owners_have_exact_supply_and_consume_kinds(){var f=Fixture();var port=new InMemoryProviderAdjacentOwnerPort(f.Plan,32);foreach(var x in Cases())Assert.IsType<ProviderAdjacentPortResult.Accepted>(port.Exchange(Message(f,x.Direction,x.Kind,x.Owner)));}
    [Fact] public void Wrong_owner_kind_pair_is_constructor_rejected(){var f=Fixture();Assert.Throws<ArgumentException>(()=>new ProviderAdjacentMessage(OperationId.Create(),ProviderAdjacentDirection.SuppliedByProvider,ProviderAdjacentKind.OutputCandidate,OwnerSliceId.S4,f.Plan.ParticipantId,f.Plan.Generation,f.Authority,new JournalPositionV1(f.Session,1),Hash(1)));}
    [Fact] public void Adjacent_evidence_cannot_replace_provider_authority(){var f=Fixture();var stale=ProviderGenerationId.Create();var authority=ExpectedAuthorityVectorV1.Create(f.Session,[new AuthorityAxisValueV1.Provider(stale),new AuthorityAxisValueV1.Route(f.Plan.RouteGeneration)]);Assert.Throws<ArgumentException>(()=>new ProviderAdjacentMessage(OperationId.Create(),ProviderAdjacentDirection.ConsumedByProvider,ProviderAdjacentKind.EndpointDecision,OwnerSliceId.S4,f.Plan.ParticipantId,f.Plan.Generation,authority,new JournalPositionV1(f.Session,1),Hash(2)));}
    [Fact] public void Retry_is_exact_and_changed_message_is_contradictory(){var f=Fixture();var port=new InMemoryProviderAdjacentOwnerPort(f.Plan,4);var message=Message(f,ProviderAdjacentDirection.SuppliedByProvider,ProviderAdjacentKind.TranscriptEvidence,OwnerSliceId.S4);Assert.IsType<ProviderAdjacentPortResult.Accepted>(port.Exchange(message));Assert.IsType<ProviderAdjacentPortResult.Duplicate>(port.Exchange(message));var changed=new ProviderAdjacentMessage(message.OperationId,message.Direction,message.Kind,message.AdjacentOwner,message.ParticipantId,message.ProviderGeneration,message.Authority,message.SourcePosition,Hash(9));Assert.Equal("provider-adjacent-operation-contradiction",Assert.IsType<ProviderAdjacentPortResult.Rejected>(port.Exchange(changed)).SafeCode.ToString());}
    [Fact] public void Port_is_bounded_without_dropping_prior_evidence(){var f=Fixture();var state=new ProviderAdjacentPortState(f.Plan);state=Assert.IsType<ProviderAdjacentPortResult.Accepted>(ProviderAdjacentOwnerReducer.Apply(state,Message(f,ProviderAdjacentDirection.SuppliedByProvider,ProviderAdjacentKind.ProviderHealth,OwnerSliceId.S8),1)).State;var rejected=Assert.IsType<ProviderAdjacentPortResult.Rejected>(ProviderAdjacentOwnerReducer.Apply(state,Message(f,ProviderAdjacentDirection.ConsumedByProvider,ProviderAdjacentKind.RouteAuthorization,OwnerSliceId.S8),1));Assert.Equal("provider-adjacent-capacity-refused",rejected.SafeCode.ToString());Assert.Single(rejected.State.Messages);}
    private static IEnumerable<(ProviderAdjacentDirection Direction,ProviderAdjacentKind Kind,OwnerSliceId Owner)> Cases(){yield return(ProviderAdjacentDirection.SuppliedByProvider,ProviderAdjacentKind.ParticipantReadiness,OwnerSliceId.S1);yield return(ProviderAdjacentDirection.ConsumedByProvider,ProviderAdjacentKind.LifecycleAdmission,OwnerSliceId.S1);yield return(ProviderAdjacentDirection.SuppliedByProvider,ProviderAdjacentKind.MediaObservation,OwnerSliceId.S2);yield return(ProviderAdjacentDirection.ConsumedByProvider,ProviderAdjacentKind.MediaLease,OwnerSliceId.S2);yield return(ProviderAdjacentDirection.SuppliedByProvider,ProviderAdjacentKind.ActivityEvidence,OwnerSliceId.S3);yield return(ProviderAdjacentDirection.ConsumedByProvider,ProviderAdjacentKind.PromotedActivity,OwnerSliceId.S3);yield return(ProviderAdjacentDirection.SuppliedByProvider,ProviderAdjacentKind.TranscriptEvidence,OwnerSliceId.S4);yield return(ProviderAdjacentDirection.ConsumedByProvider,ProviderAdjacentKind.EndpointDecision,OwnerSliceId.S4);yield return(ProviderAdjacentDirection.SuppliedByProvider,ProviderAdjacentKind.OutputCandidate,OwnerSliceId.S6);yield return(ProviderAdjacentDirection.ConsumedByProvider,ProviderAdjacentKind.PlayoutReceipt,OwnerSliceId.S6);yield return(ProviderAdjacentDirection.SuppliedByProvider,ProviderAdjacentKind.ToolProposal,OwnerSliceId.S7);yield return(ProviderAdjacentDirection.ConsumedByProvider,ProviderAdjacentKind.ToolDisposition,OwnerSliceId.S7);yield return(ProviderAdjacentDirection.SuppliedByProvider,ProviderAdjacentKind.ProviderHealth,OwnerSliceId.S8);yield return(ProviderAdjacentDirection.ConsumedByProvider,ProviderAdjacentKind.RouteAuthorization,OwnerSliceId.S8);}
    private static ProviderAdjacentMessage Message((ProviderParticipantPlan Plan,ExpectedAuthorityVectorV1 Authority,SessionAuthorityStampV1 Session) f,ProviderAdjacentDirection d,ProviderAdjacentKind k,OwnerSliceId o)=>new(OperationId.Create(),d,k,o,f.Plan.ParticipantId,f.Plan.Generation,f.Authority,new JournalPositionV1(f.Session,1),Hash((byte)k));
    private static (ProviderParticipantPlan Plan,ExpectedAuthorityVectorV1 Authority,SessionAuthorityStampV1 Session) Fixture(){var s=new SessionAuthorityStampV1(RuntimeGenerationId.Create(),LiveSessionId.Create());var p=ProviderGenerationId.Create();var r=RouteGenerationId.Create();var a=ExpectedAuthorityVectorV1.Create(s,[new AuthorityAxisValueV1.Provider(p),new AuthorityAxisValueV1.Route(r)]);return(new ProviderParticipantPlan(ParticipantId.Create(),ProviderId.Create(),p,r,a,Hash(20),2),a,s);}
    private static Hash256 Hash(byte b)=>Hash256.Compute(new[]{b});
}
